class 학생:
    def __init__(self, 이름, 점수):
        self.이름 = 이름
        self.점수 = 점수
    def 올리기(self, 얼마):
        self.점수 += 얼마
반 = [학생("민수", 70), 학생("지아", 95), 학생("하준", 80), 학생("서연", 60)]
누구 = input("이름: ")
for 한명 in 반:
    if 한명.이름 == 누구:
        한명.올리기(20)
으뜸 = 반[0]
for 한명 in 반:
    if 한명.점수 > 으뜸.점수:
        으뜸 = 한명
